from collections import deque


def shortest_bridge(grid):
    n = len(grid)
    visited = [[False] * n for _ in range(n)]

    def find_first_island():
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 1:
                    return r, c
        return -1, -1

    def mark_island(r, c, queue):
        stack = [(r, c)]
        visited[r][c] = True
        while stack:
            cr, cc = stack.pop()
            queue.append((cr, cc, 0))
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < n and 0 <= nc < n and not visited[nr][nc] and grid[nr][nc] == 1:
                    visited[nr][nc] = True
                    stack.append((nr, nc))

    start_r, start_c = find_first_island()
    queue = deque()
    mark_island(start_r, start_c, queue)

    while queue:
        r, c, dist = queue.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n and not visited[nr][nc]:
                if grid[nr][nc] == 1:
                    return dist
                visited[nr][nc] = True
                queue.append((nr, nc, dist + 1))

    return -1

